        payments: {
          bannerTitle: "Payment service currently not available",
          bannerBody: "We are building a payment service that will work directly with your UrMall items, orders, and seller records. Until it is ready, communicate payment terms clearly with buyers and keep order details inside the platform wherever possible.",
          bankTitle: "Bank Details",
          bankDesc: "Currently unavailable while UrMall payment setup is being prepared.",
          txTitle: "Transactions",
          txDesc: "Transaction records will appear after built-in payments are launched.",
          historyTitle: "Withdrawal History",
          historyDesc: "Payout history will become active when seller payouts are enabled.",
          eyebrow: "Payments & Payouts",
        },
        payDocs: {
          bank: {
            summary: "Bank details are currently not available while UrMall prepares a safer payment service connected to products, orders, and seller payouts.",
            h1t: "Coming soon",
            h1x: "Bank setup will open when the payment service is ready for seller payouts.",
            h2t: "Protect details",
            h2x: "Sensitive payout information should only be collected when it can be handled properly.",
            h3t: "Prepare now",
            h3x: "Complete your profile and verification so your store is ready for payment tools.",
            s1t: "Why bank setup is paused",
            s1p1: "Bank details are currently not available because UrMall is preparing a payment service that will connect directly to your listed items, buyer orders, seller dashboard, and payout records. We do not want sellers entering sensitive payment information into a section before the full payment flow is ready to protect it and use it correctly.",
            s1p2: "A professional marketplace payment system should do more than store an account number. It should understand the item being sold, the order amount, the buyer, the seller, the delivery or pickup state, and the payout status. That is the service being prepared.",
            s2t: "How to handle payment for now",
            s2p1: "Until built-in payments are active, discuss payment clearly with the buyer before completing the order. Confirm the product name, final price, delivery fee if any, pickup or delivery arrangement, buyer phone number, and expected payment method. Clear communication protects your business and makes the buyer feel respected.",
            s2p2: "Avoid sending confusing or changing payment instructions. If you share payment details outside the platform, make sure the buyer understands exactly what the payment is for. Keep product and order conversations inside UrMall where possible so there is a record of what was agreed.",
            s3t: "What sellers can expect next",
            s3p1: "When the payment service becomes available, this section should become the place to manage payout identity, approved payment routes, settlement status, and seller withdrawal information. The goal is to help sellers receive money with better confidence and less manual explanation.",
            s3p2: "For now, treat this page as a readiness notice. Keep your seller profile, verification status, product listings, and order details accurate so your store is prepared when payment tools become active.",
          },
          tx: {
            summary: "Transaction records will become available when UrMall's item-based payment service is launched.",
            h1t: "Not active yet",
            h1x: "Official marketplace transactions will appear only after payments go live.",
            h2t: "Clear terms",
            h2x: "Confirm item, price, fees, and payment timing with every buyer.",
            h3t: "Keep proof",
            h3x: "Maintain private records until UrMall transaction tracking is available.",
            s1t: "Transaction records are coming",
            s1p1: "Transactions are currently not available because UrMall is still building the payment service that will generate official marketplace payment records. Once that service is active, this page should show item payments, order totals, charges, refunds, pending settlements, and completed seller receipts.",
            s1p2: "We are avoiding fake or incomplete transaction screens because sellers need financial information they can trust. A transaction page should not simply look active. It should reflect real payment activity connected to real orders.",
            s2t: "How to communicate money details now",
            s2p1: "For now, explain money details to buyers in a careful and professional way. Confirm the exact item, quantity, agreed price, delivery fee, payment timing, and what happens after payment. If the buyer is paying before delivery, make sure the buyer understands the seller identity and the product being paid for.",
            s2p2: "Use simple language and avoid rushing the buyer. A good message sounds like: 'This payment is for one item, the final price is confirmed, delivery is included or excluded, and your order will be prepared after confirmation.' Clear payment communication reduces suspicion and prevents arguments.",
            s3t: "Keeping your own records",
            s3p1: "Until UrMall transactions are live, sellers should keep private records of payments received, buyer names, item names, dates, delivery arrangements, and any proof of payment. Good records help you answer buyer questions and resolve issues faster.",
            s3p2: "When built-in transactions launch, UrMall should make this process easier by tying payment records directly to item orders and seller dashboards. The long-term goal is less manual tracking and more confidence for both sides.",
          },
          history: {
            summary: "Withdrawal history will become available when UrMall enables official seller payouts from item-based payments.",
            h1t: "No payouts yet",
            h1x: "This section will activate when built-in seller withdrawals are launched.",
            h2t: "Real records",
            h2x: "Payout history should reflect actual payment settlements, not placeholders.",
            h3t: "Communicate clearly",
            h3x: "Until launch, explain payment arrangements carefully to buyers.",
            s1t: "Why payout history is not active yet",
            s1p1: "Withdrawal history is currently not available because seller payouts have not been launched inside UrMall yet. A payout history should only show real settlements from marketplace payments. Since the payment service is still being prepared, there are no official payout entries to display.",
            s1p2: "This is intentional. We want sellers to see trustworthy payout records, not placeholder balances or simulated financial activity. When the payment service is ready, payout history should become a reliable record of money released to the seller.",
            s2t: "What this page will support later",
            s2p1: "After launch, payout history should help sellers understand how much money has been released, which orders funded the payout, what is still pending, and whether any withdrawal failed or needs attention. That kind of clarity is important because sellers need to plan stock, delivery, and business cash flow.",
            s2p2: "The goal is to connect payouts to actual item sales so a seller can move from product to order to payment to withdrawal without confusion. That is why this feature is being treated as part of a proper payment system, not a separate empty page.",
            s3t: "What to do until payouts launch",
            s3p1: "Until payouts are active, agree payment arrangements carefully with buyers and keep your own payment notes. Make sure every payment conversation is connected to a product and order details. If anything feels suspicious, slow down and confirm before releasing goods.",
            s3p2: "Professional sellers should communicate in a way that helps buyers feel safe sending money: state the item, price, delivery plan, and confirmation process. Good payment communication is part of selling well, especially before built-in payouts are available.",
          },
        },
