        supportS1P2: "لمشكلات الحساب أو الأمان أو سلوك البائع المشبوه أو طلبات الدفع المزيّفة أو مشكلات الطلبات المتكررة، استخدم دعم UrMall عندما يصبح نظام التذاكر مفعّلًا. وإلى ذلك الحين، احتفظ بالأدلة واستخدم أكثر رسالة بائع أو سجل طلب صلةً بالموضوع.",
