            s1p2: "نجمع المعلومات اللازمة لتشغيل حسابات البائعين وعرض ملفات المتاجر العامة ومعالجة إجراءات السوق ودعم الطلبات والتحقيق في النزاعات وتحسين الأمان وتقديم دعم العملاء. لا نطلب معلومات غير ضرورية لمجرّد ملء قاعدة بيانات. ينبغي أن يساعد كل تفصيل المشترين على إيجاد بائعين موثوقين، أو يساعد البائعين على العمل باحترافية، أو يساعد المنصّة على تقليل الاحتيال والالتباس.",
            s2t: "ما الذي يمكن للمشترين رؤيته",
            s2p1: "بعض معلومات البائع عامة بحكم التصميم. قد يرى المشترون اسم متجرك وشعارك وفئة نشاطك التجاري ومدينتك وبلدك وخيارات الاتصال العامة وحالة التوثيق وقوائم المنتجات وتوفّر التوصيل أو الاستلام وتفاصيل أخرى تختار نشرها. هذه الرؤية جزء من البيع في سوق. لا يمكن للمشتري الوثوق بمتجر يخفي كل شيء عن نفسه.",
