            s3t: "كيف تُحمى المعلومات",
            s3p1: "حماية الخصوصية تقنية وتشغيلية معًا. ينبغي أن يقتصر الوصول إلى معلومات البائع على البائع وأنظمة المنصّة المصرّح بها وعمليات الدعم التي تحتاج إلى المعلومات لحلّ مشكلة مشروعة. قواعد الأمان وأذونات الحساب وسياسات قاعدة البيانات تساعد على منع تعرّض السجلّات الخاصة للمستخدمين الخطأ.",
